<?php
namespace App\Http\Controllers\CRM;use App\Http\Controllers\Controller;use App\Models\ZigoPaymentExportAudit;use App\Services\Exports\PaymentExportQuery;use App\Services\Exports\SimpleXlsxWriter;use Illuminate\Http\Request;
final class CrmPaymentExportController extends Controller{
 public function __invoke(Request $r,PaymentExportQuery $queries,SimpleXlsxWriter $xlsx){$data=$r->validate(['tab'=>'required|in:shipments,recharges','scope'=>'required|in:filtered,all']);$filters=$data['scope']==='filtered'?$queries->filters($r,$data['tab']):[];$filename=($data['tab']==='recharges'?'recargas':'pagos').'-zigo-'.now()->format('Ymd-His').'.xlsx';$path=storage_path('app/private/exports/'.$filename);$limit=max(1,(int)config('zigo_notifications.export_limit',25000));$count=$data['tab']==='recharges'?$this->recharges($xlsx,$path,$queries,$filters,$limit):$this->shipments($xlsx,$path,$queries,$filters,$limit);ZigoPaymentExportAudit::create(['user_id'=>$r->user()->getAuthIdentifier(),'tab'=>$data['tab'],'scope'=>$data['scope'],'filters'=>$filters,'record_count'=>$count,'filename'=>$filename]);return response()->download($path,$filename,['Content-Type'=>'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'])->deleteFileAfterSend(true);}
 private function shipments(SimpleXlsxWriter $xlsx,string $path,PaymentExportQuery $queries,array $filters,int $limit):int{return $xlsx->write($path,['Cotización','Referencia','Cliente','Email','Fecha','Método','Payment ID','Estado de pago','Estado del envío','Subtotal ZIGO','IVA','Total ZIGO'],function($append)use($queries,$filters,$limit){$seen=0;$queries->shipments($filters)->orderBy('id')->chunkById(500,function($items)use($append,$limit,&$seen){foreach($items as $q){if($seen++ >= $limit)return false;$total=(float)($q->payment_verified_amount?:$q->precio);$subtotal=round($total/1.16,2);$append([$q->id,$q->payment_external_reference?:$q->referencia,$q->user?->name,$q->user?->email,$q->payment_verified_at?->format('Y-m-d H:i:s')?:$q->updated_at?->format('Y-m-d H:i:s'),strtolower((string)$q->payment_status)==='saldo_prepago'?'Saldo prepago':'Mercado Pago',$q->payment_id,$q->payment_status,$q->estatus,$subtotal,round($total-$subtotal,2),$total]);}return true;});});}
 private function recharges(SimpleXlsxWriter $xlsx,string $path,PaymentExportQuery $queries,array $filters,int $limit):int{return $xlsx->write($path,['Recarga','Usuario','Email','Fecha','Monto','Estado','Preference ID','Payment ID','Referencia','Acreditada','Saldo anterior','Saldo nuevo'],function($append)use($queries,$filters,$limit){$seen=0;$queries->recharges($filters)->orderBy('id')->chunkById(500,function($items)use($append,$queries,$limit,&$seen){$queries->movements($items);foreach($items as $q){if($seen++ >= $limit)return false;$credited=$q->movimiento&&$q->movimiento->estatus==='APLICADO'&&(float)$q->movimiento->saldo_nuevo>(float)$q->movimiento->saldo_anterior;$append([$q->id,$q->user?->name,$q->user?->email,$q->created_at?->format('Y-m-d H:i:s'),$q->monto,$q->estatus,$q->mp_preference_id,$q->mp_payment_id,$q->referencia,$credited?'Sí':'No',$q->movimiento?->saldo_anterior,$q->movimiento?->saldo_nuevo]);}return true;});});}
}
